namespace sv_539a4909250c4de1a18e5c45e74c4d29.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                NotifyStateChanged();
            }
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A - Main Distribution",
            ["WH-002"] = "Warehouse B - East Regional",
            ["WH-003"] = "Warehouse C - West Coast",
            ["WH-004"] = "Warehouse D - Returns Processing",
        };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_539a4909250c4de1a18e5c45e74c4d29.Services;

public class InventoryAlertService
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private CancellationTokenSource? _pollCts;
    private int _activeSubscribers;
    private readonly object _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to begin polling. Polling runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _activeSubscribers++;
            if (_activeSubscribers == 1)
            {
                _pollCts = new CancellationTokenSource();
                _ = PollLoopAsync(_pollCts.Token);
            }
        }
    }

    /// <summary>
    /// Called by components when they are disposed. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
            if (_activeSubscribers == 0)
            {
                _pollCts?.Cancel();
                _pollCts?.Dispose();
                _pollCts = null;
            }
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await RefreshAsync();
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh when warehouse changes so all subscribers see fresh data.
        if (_activeSubscribers > 0)
        {
            await RefreshAsync();
        }
    }
}

