            <span class="badge @BadgeClass fs-5">@AlertService.CurrentLowStockCount</span>
        </p>
        <p class="text-muted small">
            Auto-refreshes every 10 seconds. Last checked for warehouse
            <code>@WarehouseState.CurrentWarehouseId</code>.
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How this works:</strong> This page starts polling via
    <code>InventoryAlertService</code> when mounted and stops when you navigate away.
    The sidebar badge and this panel both subscribe to the same service event —
    when new data arrives, all subscribers update simultaneously.
</div>

@code {
    private string BadgeClass => AlertService.CurrentLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        _ => "bg-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertDataChanged += OnAlertChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    private void OnAlertChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertDataChanged -= OnAlertChanged;
        AlertService.StopPolling();
    }
}

